import json, sys

def trunc(s, n=300):
    if not isinstance(s, str):
        s = json.dumps(s)[:n]
        return s
    if len(s) <= n:
        return s
    return s[:n] + f"...[{len(s)} chars]"

def summarize_content(content):
    out = []
    if isinstance(content, str):
        out.append(("text", trunc(content)))
        return out
    if isinstance(content, list):
        for c in content:
            if not isinstance(c, dict):
                out.append(("?", trunc(c)))
                continue
            t = c.get("type")
            if t == "text":
                out.append(("text", trunc(c.get("text",""))))
            elif t == "tool_use":
                out.append(("tool_use", c.get("name"), trunc(c.get("input",{}), 200)))
            elif t == "tool_result":
                cc = c.get("content")
                if isinstance(cc, list):
                    txt = " ".join(x.get("text","") for x in cc if isinstance(x, dict))
                else:
                    txt = str(cc)
                out.append(("tool_result", trunc(txt, 200)))
            else:
                out.append((t, trunc(c, 150)))
    return out

path = sys.argv[1]
with open(path) as f:
    for i, line in enumerate(f):
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception as e:
            print(f"[{i}] PARSE ERROR {e}")
            continue
        ts = obj.get("timestamp") or obj.get("time") or ""
        role = obj.get("role") or obj.get("type") or "?"
        msg = obj.get("message", obj)
        content = None
        if isinstance(msg, dict):
            content = msg.get("content")
            role = msg.get("role", role)
        else:
            content = obj.get("content")
        print(f"--- [{i}] ts={ts} role={role} ---")
        if content is not None:
            for item in summarize_content(content):
                print("   ", item)
        else:
            # print top-level keys for unknown shape
            print("   keys:", list(obj.keys()))

