import json, sys

def trunc(s, n=300):
    if not isinstance(s, str):
        s = json.dumps(s)
    s = s.replace('\n', ' \\n ')
    if len(s) > n:
        return s[:n] + f"...[{len(s)}chars]"
    return s

def content_text(content):
    if isinstance(content, str):
        return content
    parts = []
    if isinstance(content, list):
        for c in content:
            if not isinstance(c, dict):
                parts.append(str(c))
                continue
            t = c.get('type')
            if t == 'text':
                parts.append(c.get('text',''))
            elif t == 'tool_use':
                parts.append(f"[TOOL_USE {c.get('name')} input={trunc(c.get('input'),400)}]")
            elif t == 'tool_result':
                cc = c.get('content')
                if isinstance(cc, list):
                    cc = ' '.join(x.get('text','') if isinstance(x,dict) else str(x) for x in cc)
                parts.append(f"[TOOL_RESULT err={c.get('is_error')} {trunc(cc,400)}]")
            else:
                parts.append(trunc(c, 200))
    return ' '.join(parts)

def main(path):
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                d = json.loads(line)
            except Exception:
                continue
            typ = d.get('type')
            ts = d.get('timestamp','')
            if typ in ('user','assistant'):
                msg = d.get('message', {})
                role = msg.get('role', typ)
                txt = content_text(msg.get('content'))
                print(f"[{ts}] {role.upper()}: {trunc(txt, 600)}")
            elif typ == 'queue-operation':
                print(f"[{ts}] QUEUE-OP {d.get('operation')}: {trunc(d.get('content'),200)}")
            # skip attachment/hook noise and atis-latch/last-prompt

if __name__ == '__main__':
    main(sys.argv[1])

